package com.xianzhi.fridge.assistant.application;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.xianzhi.fridge.assistant.api.AssistantContracts;
import com.xianzhi.fridge.assistant.infrastructure.AssistantStore;
import com.xianzhi.fridge.shared.application.IdempotencyService;
import com.xianzhi.fridge.shared.domain.Hashing;
import com.xianzhi.fridge.shared.domain.UuidV7;
import com.xianzhi.fridge.shared.web.ApiException;
import com.xianzhi.fridge.shopping.api.ShoppingContracts;
import com.xianzhi.fridge.shopping.application.ShoppingService;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class AssistantService {
    private final AssistantStore store;private final AssistantContextAssembler contexts;private final ShoppingService shopping;private final IdempotencyService idempotency;private final AssistantProperties properties;private final ObjectMapper mapper;private final Clock clock;
    public AssistantService(AssistantStore store,AssistantContextAssembler contexts,ShoppingService shopping,IdempotencyService idempotency,AssistantProperties properties,ObjectMapper mapper,Clock clock){this.store=store;this.contexts=contexts;this.shopping=shopping;this.idempotency=idempotency;this.properties=properties;this.mapper=mapper;this.clock=clock;}
    public AssistantContracts.Briefing briefing(UUID userId){return new AssistantContracts.Briefing(store.insights(userId),store.pending(userId),store.unreadNotifications(userId),!properties.isExternalCallsEnabled());}
    @Transactional public AssistantContracts.ConversationView create(UUID userId,String key,AssistantContracts.CreateConversationRequest request){String path="/api/v1/assistant/conversations";var replay=idempotency.replay(userId,key,"POST",path,request,AssistantContracts.ConversationView.class);if(replay!=null)return replay;var result=store.createConversation(UuidV7.next(),userId,request.title(),clock.instant());idempotency.save(userId,key,"POST",path,request,result,200);return result;}
    @Transactional public AssistantContracts.MessageResponse message(UUID userId,UUID conversationId,String key,AssistantContracts.MessageRequest request){String path="/api/v1/assistant/conversations/"+conversationId+"/messages";var replay=idempotency.replay(userId,key,"POST",path,request,AssistantContracts.MessageResponse.class);if(replay!=null)return replay;if(store.conversation(conversationId,userId)==null)throw new ApiException(HttpStatus.NOT_FOUND,"ASSISTANT_CONVERSATION_NOT_FOUND","Assistant conversation not found");var context=contexts.assemble(userId,request.page(),request.selection());Instant now=clock.instant();UUID snapshot=store.snapshot(UuidV7.next(),userId,context.version(),context.json(),context.sources(),now.plus(Duration.ofHours(24)),now);String selection=json(request.selection()==null?mapper.createObjectNode():request.selection());store.message(UuidV7.next(),conversationId,userId,"USER",request.content(),request.page(),selection,"[]",snapshot,context.version(),null,"ACCEPTED",now);List<AssistantContracts.Citation> citations=context.inventory().stream().limit(3).map(item->new AssistantContracts.Citation("INVENTORY_ITEM",item.id(),item.name()+(item.lowStock()?"：库存偏低":""))).toList();List<AssistantContracts.ProposalView> proposals=new ArrayList<>();String answer;String text=request.content();if(text.contains("菜谱")||text.contains("吃什么")||text.contains("做什么")){answer=context.inventory().isEmpty()?"当前没有可用库存记录，可以先添加食材，再生成更准确的菜谱候选。":"我可以基于当前 "+context.inventory().size()+" 种库存食材生成规则菜谱候选。";proposals.add(store.proposal(UuidV7.next(),userId,conversationId,"CREATE_RECIPE_CANDIDATES","生成当前库存菜谱候选",selection,context.version(),now.plus(Duration.ofMinutes(30)),now));}else if(text.contains("采购")||text.contains("购物")||text.contains("买")){JsonNode sel=request.selection();if(sel!=null&&sel.hasNonNull("listId")&&sel.hasNonNull("itemName")){ObjectNode payload=mapper.createObjectNode();payload.put("listId",sel.path("listId").asText());payload.put("name",sel.path("itemName").asText());payload.put("quantity",sel.path("quantity").asDouble(1));payload.put("unit",sel.path("unit").asText("piece"));proposals.add(store.proposal(UuidV7.next(),userId,conversationId,"CREATE_SHOPPING_CANDIDATE","加入购物清单",json(payload),context.version(),now.plus(Duration.ofMinutes(30)),now));answer="已生成购物清单操作草案，确认后才会写入数据。";}else{answer="请先在采购页面选择清单和食材，我会生成待确认草案。";proposals.add(store.proposal(UuidV7.next(),userId,conversationId,"NAVIGATE","打开采购页面","{\"path\":\"/app/shopping\"}",context.version(),now.plus(Duration.ofMinutes(30)),now));}}else answer="我已读取当前页面、库存和偏好状态。你可以询问临期处理、库存菜谱或采购建议。";String citationJson=json(citations);var assistant=store.message(UuidV7.next(),conversationId,userId,"ASSISTANT",answer,request.page(),selection,citationJson,snapshot,context.version(),properties.isExternalCallsEnabled()?properties.getModelName():"rules-v1","COMPLETED",clock.instant());var result=new AssistantContracts.MessageResponse(assistant,citations,proposals,!properties.isExternalCallsEnabled());idempotency.save(userId,key,"POST",path,request,result,200);return result;}
    @Transactional public AssistantContracts.ActionResult confirm(UUID userId,UUID id,String key){String path="/api/v1/assistant/action-proposals/"+id+"/confirm";var replay=idempotency.replay(userId,key,"POST",path,id,AssistantContracts.ActionResult.class);if(replay!=null)return replay;var proposal=owned(userId,id);if(!"PENDING_CONFIRMATION".equals(proposal.status()))throw new ApiException(HttpStatus.CONFLICT,"ACTION_PROPOSAL_NOT_PENDING","Action proposal is no longer pending");if(!clock.instant().isBefore(proposal.expiresAt())||!proposal.contextVersion().equals(contexts.assemble(userId,null,null).version()))throw new ApiException(HttpStatus.CONFLICT,"CONTEXT_STALE","Assistant context is stale");JsonNode payload=read(proposal.payload());JsonNode result;if("CREATE_SHOPPING_CANDIDATE".equals(proposal.type())){UUID listId=UUID.fromString(payload.path("listId").asText());String nested="assistant-"+Hashing.sha256(userId+":"+key).substring(0,64);var item=shopping.addItem(userId,listId,nested,new ShoppingContracts.CreateItemRequest(payload.path("name").asText(),"OTHER",payload.path("quantity").decimalValue(),payload.path("unit").asText("piece"),"AI 待确认建议","AI_CONFIRMED"));result=mapper.valueToTree(item);}else result=payload;store.complete(id,"CONFIRMED",json(result),clock.instant());var response=new AssistantContracts.ActionResult(id,"CONFIRMED",result);idempotency.save(userId,key,"POST",path,id,response,200);return response;}
    @Transactional public AssistantContracts.ActionResult dismiss(UUID userId,UUID id,String key){String path="/api/v1/assistant/action-proposals/"+id+"/dismiss";var replay=idempotency.replay(userId,key,"POST",path,id,AssistantContracts.ActionResult.class);if(replay!=null)return replay;owned(userId,id);JsonNode result=mapper.createObjectNode();store.complete(id,"DISMISSED","{}",clock.instant());var response=new AssistantContracts.ActionResult(id,"DISMISSED",result);idempotency.save(userId,key,"POST",path,id,response,200);return response;}
    private AssistantStore.ProposalRow owned(UUID userId,UUID id){var row=store.proposalRow(id,userId);if(row==null)throw new ApiException(HttpStatus.NOT_FOUND,"ACTION_PROPOSAL_NOT_FOUND","Action proposal not found");return row;}
    private String json(Object value){try{return mapper.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalStateException(e);}}private JsonNode read(String value){try{return mapper.readTree(value);}catch(JsonProcessingException e){throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"AI_OUTPUT_INVALID","Stored action proposal is invalid");}}
}
